/**
 * EarthMap
 * --------
 * A real-Earth stand-in for WorldMap: same interface (`heightAt(x, y, z)`,
 * `.options`, `.signature()`, `.reseed()`), but the terrain comes from an
 * embedded land/sea raster instead of noise, so OuterWorlds can switch
 * between "a planet" and "the planet" without the renderer knowing or
 * caring which one it's drawing - see world below.
 *
 * The raster is a 1-degree equirectangular grid (360 columns x 181 rows,
 * -180..179 degrees of longitude by -90..90 of latitude), built offline
 * from Natural Earth's public-domain 110m-scale land polygons
 * (naturalearthdata.com, no attribution required) by rasterizing them with
 * a scanline point-in-polygon test and baking the result into the one
 * signed byte per cell below. One degree is deliberately coarse: this
 * effect's own sampling never asks for better than about a third of a
 * degree per point even on a large element at the finest Detail setting
 * (the frame-budget cap in outer-worlds.js catches it first), and the
 * halftone/wireframe/map styles are stylizations that forgive a simplified
 * coastline far more readily than they would forgive a shortfall in the
 * terrain actually being Earth's.
 *
 * There is no real elevation baked in - that would be a second dataset for
 * a difference only `'wire'`'s relief would show. Instead each land cell
 * stores a synthetic height that climbs with its distance from the nearest
 * coast (capped at 8 cells, roughly 900km inland) and every sea cell is a
 * flat depth below the lowest `seaLevel` the demo's own slider allows. That
 * reproduces the one thing every style actually reads from elevation - a
 * ramp from the waterline up to "fully land" - without needing to know a
 * single real mountain's height.
 *
 * Height is stored as `round(value * 200)` in a signed byte, decoded by
 * dividing back down - +-1.275 of range at a ~0.005 step, comfortably
 * covering WorldMap's own output range so the two are interchangeable to
 * every renderer path that reads a height.
 */
(function (global) {
  const COLS = 360;
  const ROWS = 181;
  const SEA_LEVEL = 0.1;

  let bytes = null;

  // Decoded once, on first use, and shared by every EarthMap instance -
  // there is only one Earth, so there is no reason to carry one decoded
  // copy per element the way each gets its own WorldMap.
  function data() {
    if (!bytes) {
      const bin = global.atob(DATA_B64);
      const n = bin.length;
      bytes = new Int8Array(n);
      // Int8Array's element setter performs ToInt8 itself (reduces mod 256
      // and reinterprets as signed), which is exactly the decode the bytes
      // below were encoded for - no manual sign-fix needed.
      for (let i = 0; i < n; i++) bytes[i] = bin.charCodeAt(i);
    }
    return bytes;
  }

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  // Bilinear sample of the raster at a longitude/latitude in degrees.
  // Longitude wraps (column 359 and column 0 are neighbours); latitude
  // clamps at the poles, which are real edges of the data rather than
  // something to wrap around.
  function sampleDeg(lonDeg, latDeg) {
    const d = data();
    let fx = (lonDeg + 180) % 360;
    if (fx < 0) fx += 360;
    let fy = latDeg + 90;
    if (fy < 0) fy = 0;
    else if (fy > ROWS - 1) fy = ROWS - 1;

    const x0 = Math.floor(fx);
    const y0 = Math.floor(fy);
    const tx = fx - x0;
    const ty = fy - y0;
    const x1 = x0 + 1 === COLS ? 0 : x0 + 1;
    const y1 = Math.min(ROWS - 1, y0 + 1);

    const r0 = y0 * COLS;
    const r1 = y1 * COLS;
    const h00 = d[r0 + x0];
    const h10 = d[r0 + x1];
    const h01 = d[r1 + x0];
    const h11 = d[r1 + x1];
    const a = h00 + (h10 - h00) * tx;
    const b = h01 + (h11 - h01) * tx;
    return (a + (b - a) * ty) / 200;
  }

  class EarthMap {
    // `options` is accepted (and generator-shaped options inside it are
    // ignored) purely so EarthMap is a drop-in for WorldMap at the call
    // site in outer-worlds.js - there is nothing here for `frequency` or
    // `seed` to drive, since there is only the one planet.
    constructor(options = {}) {
      this.options = { seed: 1, ...options };
    }

    // Same signature as WorldMap.heightAt: a point on (or near) the unit
    // sphere, x/z spanning the equator and y pointing at the north pole.
    heightAt(x, y, z) {
      const lat = Math.asin(y < -1 ? -1 : y > 1 ? 1 : y);
      const lon = Math.atan2(z, x);
      return sampleDeg((lon * 180) / Math.PI, (lat * 180) / Math.PI);
    }

    // No seed drives this map, so reseeding is a no-op - kept only so a
    // caller that treats every map the same (OuterWorlds.newWorld) has
    // nothing to special-case.
    reseed() {
      return this.options.seed;
    }

    // Identity of the generated field. Constant, since there is exactly one
    // Earth: switching seaLevel/landRange re-floods it like WorldMap's own
    // classification-only options do, and never needs a rebuild.
    signature() {
      return 'earth';
    }

    isLand(h) {
      return h > (this.options.seaLevel ?? SEA_LEVEL);
    }

    landFactor(h) {
      const seaLevel = this.options.seaLevel ?? SEA_LEVEL;
      const landRange = this.options.landRange ?? 0.42;
      return clamp01((h - seaLevel) / landRange);
    }
  }

  EarthMap.signatureOf = function signatureOf() {
    return 'earth';
  };

  const DATA_B64 =
    "";

  global.EarthMap = EarthMap;
})(typeof window !== 'undefined' ? window : globalThis);
